mapper.select:
SELECT id, ds_id, thread_id, question, query_elements_json, matched_elements_json,
       missing_elements_json, channel_hit_json, context_item_count, context_token_estimate,
       cold_start, allow_cold_start, space_used, kb_b_unavailable, rerank_enabled,
       latency_ms, matched_template_id, matched_flag, create_time
FROM rcagent_retrieval_log


        AND ds_id = #{dsId}


        AND thread_id = #{threadId}


        AND cold_start = #{coldStart}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC, id DESC

SELECT COUNT(*)                         AS total_search,
       COALESCE(SUM(cold_start), 0)     AS cold_start_count,
       ROUND(COALESCE(SUM(cold_start), 0) * 1.0 / COUNT(*), 2) AS cold_start_rate,
       ROUND(COALESCE(AVG(latency_ms), 0))  AS avg_latency_ms,
       ROUND(COALESCE(AVG(context_item_count), 0), 2) AS avg_context_items,
       ROUND(COALESCE(SUM(kb_b_unavailable), 0) * 1.0 / COUNT(*), 2) AS kb_b_degrade_rate
FROM rcagent_retrieval_log


        AND ds_id = #{dsId}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}

SELECT
DATE_FORMAT(create_time, '%x-W%v') AS bucket
DATE_FORMAT(create_time, '%Y-%m-%d') AS bucket
, COUNT(*) AS search_count, COALESCE(SUM(cold_start), 0) AS cold_start_count, ROUND(COALESCE(AVG(latency_ms), 0)) AS avg_latency_ms FROM rcagent_retrieval_log
AND ds_id = #{dsId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY bucket ORDER BY bucket ASC
